  "componentes/breadcrumb|Caminho longo, recolhido": {
    "html": "<nav mxBreadcrumb aria-label=\"Localização recolhida\">\n  <ol>\n    <li><a routerLink=\"/\">Início</a></li>\n    <li>\n      <button type=\"button\" aria-label=\"Mostrar níveis escondidos\" [mxMenuTriggerFor]=\"niveis\">…</button>\n      <ng-template #niveis>\n        <div mxMenu>\n          <a mxMenuItem routerLink=\"/componentes\">Clientes</a>\n          <a mxMenuItem routerLink=\"/componentes\">Empresas</a>\n          <a mxMenuItem routerLink=\"/componentes\">Kianda Logística</a>\n        </div>\n      </ng-template>\n    </li>\n    <li><a routerLink=\"/componentes\">Facturas</a></li>\n    <li><span aria-current=\"page\">FT 2026/0142</span></li>\n  </ol>\n</nav>",
    "ts": "import { Component } from '@angular/core';\nimport { RouterLink } from '@angular/router';\nimport { MxBreadcrumb } from '@muxima-ui/core/breadcrumb';\nimport { MX_COMMAND } from '@muxima-ui/core/command';\nimport { MX_MENU } from '@muxima-ui/core/menu';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxBreadcrumb, MX_COMMAND, MX_MENU, RouterLink],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "componentes/breadcrumb|No cabeçalho de uma página": {
    "html": "<div>\n  <nav mxBreadcrumb aria-label=\"Localização da página\">\n    <ol>\n      <li><a routerLink=\"/\">Início</a></li>\n      <li><a routerLink=\"/componentes\">Facturas</a></li>\n      <li><span aria-current=\"page\">Nova factura</span></li>\n    </ol>\n  </nav>\n  <div><h3>Nova factura</h3><button mxButton type=\"button\" size=\"sm\">Emitir</button></div>\n</div>",
    "ts": "import { Component } from '@angular/core';\nimport { RouterLink } from '@angular/router';\nimport { MxBreadcrumb } from '@muxima-ui/core/breadcrumb';\nimport { MxButton } from '@muxima-ui/core/button';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxBreadcrumb, MxButton, RouterLink],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "componentes/breadcrumb|Só voltar, em telemóvel": {
    "html": "<nav mxBreadcrumb aria-label=\"Voltar\">\n  <ol>\n    <li><a routerLink=\"/componentes\"><svg aria-hidden=\"true\">…</svg> Facturas</a></li>\n  </ol>\n</nav>",
    "ts": "import { Component } from '@angular/core';\nimport { RouterLink } from '@angular/router';\nimport { MxBreadcrumb } from '@muxima-ui/core/breadcrumb';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxBreadcrumb, RouterLink],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "componentes/breadcrumb|Estados": {
    "html": "<!-- Ligação -->\n<nav mxBreadcrumb aria-label=\"Ligação\"><ol><li><a href=\"#\">Clientes</a></li></ol></nav>\n\n<!-- Hover -->\n<nav mxBreadcrumb aria-label=\"Hover\"><ol><li><a href=\"#\" data-mx-state=\"hover\">Clientes</a></li></ol></nav>\n\n<!-- Foco -->\n<nav mxBreadcrumb aria-label=\"Foco\"><ol><li><a href=\"#\" data-mx-state=\"focus\">Clientes</a></li></ol></nav>\n\n<!-- Página actual: aria-current=page -->\n<nav mxBreadcrumb aria-label=\"Actual\"><ol><li><span aria-current=\"page\">Facturas</span></li></ol></nav>",
    "ts": "import { Component } from '@angular/core';\nimport { MxBreadcrumb } from '@muxima-ui/core/breadcrumb';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxBreadcrumb],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {}"
  },
  "componentes/pagination|Com uma tabela": {
    "html": "<div>\n  <div class=\"mx-table-container\">\n    <table mxTable density=\"compact\">\n      <caption>Clientes {{ from() }} a {{ to() }} de 47</caption>\n      <thead><tr><th scope=\"col\">N.º</th><th scope=\"col\">Nome</th></tr></thead>\n      <tbody>\n        @for (c of rows(); track c.id) {\n          <tr><td>{{ c.id }}</td><td>{{ c.nome }}</td></tr>\n        }\n      </tbody>\n    </table>\n  </div>\n  <span class=\"mx-visually-hidden\" aria-live=\"polite\">Página {{ tablePage() }}, clientes {{ from() }} a {{ to() }}</span>\n  <mx-pagination [(page)]=\"tablePage\" [total]=\"47\" [pageSize]=\"5\" aria-label=\"Páginas de clientes\" />\n</div>",
    "ts": "import { Component, signal, computed } from '@angular/core';\nimport { MxPagination } from '@muxima-ui/core/pagination';\nimport { MX_TABLE } from '@muxima-ui/core/table';\n\nconst CLIENTES = Array.from({ length: 47 }, (_, i) => ({ id: i + 1, nome: `Cliente ${String(i + 1).padStart(2, '0')}` }));\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxPagination, MX_TABLE],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly tablePage = signal(1);\n\n  protected readonly from = computed(() => (this.tablePage() - 1) * 5 + 1);\n\n  protected readonly to = computed(() => Math.min(this.tablePage() * 5, 47));\n\n  protected readonly rows = computed(() => CLIENTES.slice(this.from() - 1, this.to()));\n}"
  },
  "componentes/pagination|Simples": {
    "html": "<mx-pagination variant=\"simple\" [(page)]=\"page3\" [total]=\"120\" [pageSize]=\"10\" aria-label=\"Exemplo simples\" />",
    "ts": "import { Component, signal } from '@angular/core';\nimport { MxPagination } from '@muxima-ui/core/pagination';\n\n@Component({\n  selector: 'app-exemplo',\n  imports: [MxPagination],\n  templateUrl: './exemplo.html',\n})\nexport class Exemplo {\n  protected readonly page3 = signal(4);\n}"
  },
